// Concatenates apps-script/*.js into dist/ZOFF-Champions.gs for a single copy-paste install.
const fs = require('fs');
const order = ['Config', 'Rules', 'Store', 'Intake', 'Leaderboard', 'MonthEnd', 'Setup'];
const out = ['// ZOFF Champions: all Apps Script files in one. Paste into Extensions > Apps Script (Code.gs).',
  "// Generated by 'npm run bundle' from apps-script/. Edit those files, not this one."];
for (const f of order) out.push('', '// ===== ' + f + '.js =====', fs.readFileSync('apps-script/' + f + '.js', 'utf8'));
new Function(out.join('\n')); // syntax check
fs.mkdirSync('dist', { recursive: true });
fs.writeFileSync('dist/ZOFF-Champions.gs', out.join('\n'));
fs.copyFileSync('apps-script/appsscript.json', 'dist/appsscript.json');
console.log('Wrote dist/ZOFF-Champions.gs');
